-- ============================================================================
-- PARTIE 22 — Contenu du module 10 « Prévention de la maltraitance et prendre soin de soi » (3 séquences)
-- Source : Projet pédagogique Koalakids (ne pas punir ou isoler, violence et isolement
-- comme faute professionnelle, violences éducatives ordinaires, « avant d'arriver à
-- la faute », citation de Janusz Korczak).
-- Le projet pédagogique ne décrit aucune procédure de signalement entre collègues :
-- ce volet n'est pas couvert par ce module.
-- Script reconstitué à partir de la base (contenu publié).
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 22.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Un enfant n'est jamais « méchant » : on ne punit pas, on n'isole pas, et on n'accepte aucune violence, même ordinaire.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de citer des pratiques qui relèvent de la violence éducative ordinaire et de dire pourquoi elles n'ont pas leur place auprès de jeunes enfants.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 4, "attendu": "Éthique professionnelle et bientraitance"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Rappeler que l'on parle de pratiques, pas de personnes, et que chacun peut se tromper un jour."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Un enfant n'est jamais « méchant » : on ne punit pas, on n'isole pas, et on n'accepte aucune violence, même ordinaire.", "idees": ["Un enfant n'est jamais « méchant » ou « vicieux » : il ne fait pas de bêtises, il fait des expériences pour comprendre le monde. Il a besoin de soutien et d'accompagnement, pas d'être blessé dans ses émotions. On ne punit pas, on n'isole pas.", "Toute violence physique ou verbale et tout isolement d'un enfant sont considérés comme une faute professionnelle.", "Les violences éducatives ordinaires, autrefois jugées banales, font partie des violences faites aux enfants : faire un soin sans dire à l'enfant ce qui lui arrive, agir sur sa personne sans son autorisation, tenir des paroles dévalorisantes ou blessantes, faire du chantage, se moquer, mentir, culpabiliser, lui mettre une étiquette, dévaloriser ses parents devant lui, avoir des gestes brusques ou brutaux."], "support": "Projet pédagogique Koalakids, « Ne pas punir ou isoler des enfants »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir une parole ou un geste entendu ou vu cette semaine sur le site, sans nommer d'enfant ni de collègue. On analyse la pratique, pas la personne.", "questions": ["Que s'est-il passé ? (les mots, les gestes, les faits)", "Qu'a pu comprendre ou ressentir l'enfant ?", "Cette pratique fait-elle partie des violences éducatives ordinaires ? Pourquoi ?", "Que dire ou faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : prévenir l'enfant avant de le toucher pour un soin.", "Exemple : repérer une parole dévalorisante entendue sur le site et la reformuler.", "Exemple : remplacer un chantage par une limite posée simplement."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant ni de collègue.", "Annoncer la séance 2/3 : analyse d'une situation vécue, avec un focus sur ce qui précède la faute et sur l'aide à demander."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 10 % 1/3 %';
-- FIN 22.1a

-- ---------------------------------------------------------------------------
-- 22.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Une faute professionnelle, même ordinaire", "paragraphes": ["Pendant longtemps, certaines paroles et certains gestes envers les enfants ont semblé **banals et normaux**. On sait aujourd'hui qu'ils font partie des violences faites aux enfants.", "Cette première séance pose un repère : un enfant n'est jamais « méchant », il **fait des expériences**. On ne le punit pas, on ne l'isole pas, et on ne tolère aucune violence, même ordinaire."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Pas de punition, pas d'isolement :** toute violence physique ou verbale et tout isolement d'un enfant sont une faute professionnelle.", "**Les violences ordinaires comptent :** soin sans explication, geste sans autorisation, parole dévalorisante, chantage, moquerie, mensonge, culpabilisation, étiquette, gestes brusques.", "**Ses parents aussi :** on ne dévalorise jamais les parents en présence de l'enfant."]}$kk$),
  (2,'comparaison',$kk${"intro": "Face à un enfant qui dépasse les limites.", "plutot": ["Dire à l'enfant ce que je vais faire avant de le toucher.", "Poser une limite simplement, à sa hauteur.", "Voir une expérience là où l'on est tenté de voir une bêtise.", "Rester près de lui, l'accompagner."], "eviter": ["Punir ou isoler l'enfant.", "Faire du chantage, se moquer, culpabiliser.", "Lui mettre une étiquette (« méchant », « vicieux »).", "Avoir des gestes brusques ou brutaux."]}$kk$),
  (3,'reflexion',$kk${"question": "Y a-t-il une parole ou une habitude, sur le site ou dans votre parcours, qui vous paraissait normale et que vous regardez autrement aujourd'hui ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Trois questions avant d'agir", "etapes": [{"titre": "Lui ai-je dit ce que je vais faire ?", "texte": "Je préviens l'enfant avant de le toucher ou de le déplacer."}, {"titre": "Mes mots le blessent-ils ?", "texte": "Je vérifie qu'ils ne dévalorisent ni lui ni ses parents."}, {"titre": "Suis-je en train de le punir ou de l'isoler ?", "texte": "Je reste près de lui et je l'accompagne."}], "note": "Choisissez une seule de ces questions et posez-la toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 10 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 22.1b

-- ---------------------------------------------------------------------------
-- 22.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Avant d'arriver à la faute : parler de ce que l'on ressent, demander de l'aide, analyser en équipe.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de repérer les signes qui précèdent un geste ou une parole inadaptés, et de dire à qui et comment demander de l'aide dans l'équipe.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 4, "attendu": "Éthique professionnelle et bientraitance"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Rappeler que l'on parle de pratiques, pas de personnes, et que demander de l'aide est une force."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "On ne glisse pas vers la faute d'un coup : on repère ce que l'on ressent et on s'appuie sur l'équipe.", "idees": ["Avant d'arriver à la faute, trois leviers sont indispensables : parler de ses propres émotions, demander de l'aide quand on n'en peut plus, analyser en équipe les difficultés.", "Pour se laisser toucher par les émotions des enfants sans les nier ni les enflammer, les professionnels ont besoin de maîtriser les leurs.", "Accompagner un enfant ne veut pas dire le laisser faire ce qu'il veut en dehors de tout cadre, ce qui serait maltraitant. On pose un cadre sécurisant et repérant, adapté à ses compétences, avec un choix possible à l'intérieur, et des limites et des modes d'intervention communs à l'équipe."], "support": "Projet pédagogique Koalakids, « Considérer toute violence physique, verbale et tout isolement d'un enfant comme une faute professionnelle »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un moment de la semaine où la tension est montée face à un enfant, sans nommer d'enfant ni de collègue. On analyse ce qui s'est passé en nous, pas la personne.", "questions": ["Que s'est-il passé ? (les faits)", "Qu'ai-je ressenti, et à quel moment ?", "De quoi aurais-je eu besoin (un relais, une pause, l'avis d'une collègue) ?", "Qu'est-ce que l'équipe peut mettre en place ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : dire à une collègue « Je n'en peux plus, tu peux prendre le relais ? ».", "Exemple : nommer à voix haute une émotion que je ressens face à un enfant.", "Exemple : proposer à l'équipe un temps pour analyser une situation difficile."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant ni de collègue.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur prendre soin de soi et de l'équipe."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 10 % 2/3 %';
-- FIN 22.2a

-- ---------------------------------------------------------------------------
-- 22.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Avant d'arriver à la faute", "paragraphes": ["Personne ne se réveille un matin en voulant mal faire. La fatigue, la tension, un enfant qui pleure depuis longtemps : **on glisse peu à peu**. C'est pourquoi il faut agir avant.", "Trois leviers sont indispensables : **parler de ses émotions, demander de l'aide quand on n'en peut plus, analyser en équipe les difficultés.**"]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "Elle sent la colère monter et se tait", "texte": "En fin de journée, un enfant pleure depuis longtemps. Une professionnelle, épuisée, sent la colère monter. Elle continue seule, sans rien dire.", "analyse": "c'est un signe à repérer. Avant d'arriver à la faute, on peut le dire et demander de l'aide : « Je n'en peux plus, tu peux prendre le relais ? » Demander de l'aide fait partie du métier."}, {"lettre": "B", "titre": "Une menace d'isolement", "texte": "Un collègue lance à un enfant : « Si tu continues, tu vas dans le couloir. »", "analyse": "isoler un enfant est une faute professionnelle. On analyse la situation en équipe, sans juger la personne : qu'est-ce qui a manqué (relais, pause, cadre commun) ?"}, {"lettre": "C", "titre": "Laisser faire pour éviter le conflit", "texte": "Pour éviter les pleurs, une professionnelle laisse Jules faire tout ce qu'il veut.", "analyse": "laisser faire sans cadre serait maltraitant pour l'enfant. On pose un cadre sécurisant et repérant, avec un choix possible à l'intérieur, et des limites communes à toute l'équipe."}]}$kk$),
  (2,'comparaison',$kk${"intro": "Quand la tension monte.", "plutot": ["Dire que je n'en peux plus et demander le relais.", "Nommer ce que je ressens.", "Analyser les difficultés en équipe.", "Poser un cadre sécurisant avec un choix possible."], "eviter": ["Continuer seul quand la tension monte.", "Punir ou isoler l'enfant.", "Laisser faire sans cadre.", "Garder pour soi une difficulté."]}$kk$),
  (3,'reflexion',$kk${"question": "Quel est, pour vous, le premier signe que votre patience s'use ? À qui, dans l'équipe, pourriez-vous le dire ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche à se connaître. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Trois questions quand la tension monte", "etapes": [{"titre": "Qu'est-ce que je ressens ?", "texte": "Je le nomme, au moins pour moi."}, {"titre": "De quoi ai-je besoin ?", "texte": "Un relais, une pause, l'avis d'une collègue."}, {"titre": "Qui peut m'aider ?", "texte": "Je le demande tout de suite, sans attendre d'être à bout."}], "note": "On analyse la pratique, jamais la personne."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 10 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 22.2b

-- ---------------------------------------------------------------------------
-- 22.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Prendre soin de soi pour continuer à prendre soin des enfants : l'équipe est notre ressource.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée pour prendre soin de soi et de l'équipe, et l'équipe a choisi une pratique commune pour s'entraider.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 4, "attendu": "Éthique professionnelle et bientraitance"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Prendre soin de soi n'est pas un luxe : c'est ce qui permet de rester juste avec les enfants.", "idees": ["S'élever jusqu'à la hauteur des sentiments des enfants fatigue plus que de se baisser à leur niveau : ce métier est exigeant, et le dire n'est pas une faiblesse.", "Parler de ses propres émotions, c'est aussi un modèle pour les enfants : on nomme ce que l'on ressent dans la relation (« Je suis content de te voir ce matin »).", "L'équipe analyse ensemble les difficultés et définit des limites et des modes d'intervention communs : on n'est pas seul face à une situation."], "support": "Projet pédagogique Koalakids, « Avant d'arriver à la faute… » et citation de Janusz Korczak, « Quand je redeviendrai petit »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'est-ce que cela a changé pour moi, pour l'enfant ou pour l'équipe, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant ni de collègue.", "Tour de table : ce que je retiens du module 10 et de l'ensemble du programme. Annoncer la suite et la date de la prochaine séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 10 % 3/3 %';
-- FIN 22.3a

-- ---------------------------------------------------------------------------
-- 22.3b Blocs de la séquence 3/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Prendre soin de soi, c'est prendre soin des enfants", "paragraphes": ["Accompagner de jeunes enfants demande de **s'élever jusqu'à la hauteur de leurs sentiments**. C'est exigeant, et parfois épuisant. Le dire n'est pas une faiblesse : c'est ce qui permet de rester juste avec eux.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** pour vous entraider."]}$kk$),
  (1,'citation',$kk${"texte": "« Vous dites : c'est épuisant de s'occuper des enfants. Vous avez raison.\nVous ajoutez : parce que nous devons nous mettre à leur niveau. Nous baisser, nous pencher, nous courber, nous rapetisser.\nLà vous vous trompez. Ce n'est pas tant cela qui fatigue le plus que le fait d'être obligés de nous élever jusqu'à la hauteur de leurs sentiments. De nous élever, nous étirer, nous mettre sur la pointe des pieds, nous tendre, pour ne pas les blesser. »\nJanusz Korczak, Quand je redeviendrai petit (prologue)"}$kk$),
  (2,'retenir',$kk${"titre": "À retenir", "points": ["**Parler de ses émotions,** c'est aussi un modèle pour les enfants : on nomme ce que l'on ressent.", "**Demander de l'aide** quand on n'en peut plus : c'est le premier levier avant la faute.", "**L'équipe est une ressource :** on analyse les difficultés ensemble et on s'appuie sur des limites et des modes d'intervention communs."]}$kk$),
  (3,'reflexion',$kk${"question": "Qu'est-ce qui vous aide, dans l'équipe, à tenir les jours difficiles ? Qu'est-ce qui vous manque ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche ce qui rendrait l'entraide plus simple.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un geste simple d'entraide, que chacun décrit de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 10 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 22.3b

-- ---------------------------------------------------------------------------
-- 22c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 5 / 5.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 10 %/3 %' order by m.ordre;
-- FIN 22c
